<?php
declare(strict_types=1);

namespace Automattic\BlocksEngine\PhpTransformer\WordPress;

/**
 * Shared, narrow policy for Gutenberg classes generated by core save().
 */
final class GeneratedGutenbergClassPolicy
{
    /**
     * @var array<string, string>
     */
    private const BASE_CLASSES = array(
        'core/cover' => 'wp-block-cover',
        'core/group'     => 'wp-block-group',
        'core/columns'   => 'wp-block-columns',
        'core/column'    => 'wp-block-column',
        'core/buttons'   => 'wp-block-buttons',
        'core/button'    => 'wp-block-button',
        'core/details'   => 'wp-block-details',
        'core/heading'   => 'wp-block-heading',
        'core/list'      => 'wp-block-list',
        'core/media-text' => 'wp-block-media-text',
        'core/quote'     => 'wp-block-quote',
        'core/separator' => 'wp-block-separator',
    );

    /**
     * @var array<string, array<int, string>>
     */
    private const EXTRA_CLASSES = array(
        'core/separator' => array( 'has-alpha-channel-opacity', 'has-css-opacity' ),
    );

    /**
     * @return array<int, string>
     */
    public static function classesForBlock(string $blockName): array
    {
        return array_values(array_filter(array_merge(
            array( self::baseClassForBlock($blockName) ),
            self::extraClassesForBlock($blockName)
        ), static fn (string $class): bool => '' !== $class));
    }

    public static function baseClassForBlock(string $blockName): string
    {
        return self::BASE_CLASSES[$blockName] ?? '';
    }

    /**
     * @return array<int, string>
     */
    public static function extraClassesForBlock(string $blockName): array
    {
        return self::EXTRA_CLASSES[$blockName] ?? array();
    }

    public static function isGeneratedClassName(string $className): bool
    {
        return str_starts_with($className, 'wp-block-')
            || str_starts_with($className, 'wp-element-')
            || str_starts_with($className, 'wp-container-')
            || str_starts_with($className, 'is-layout-')
            || in_array($className, array( 'has-alpha-channel-opacity', 'has-css-opacity', 'has-text-color', 'has-background', 'has-link-color' ), true);
    }
}
